mapper.sql:
WHERE task.tenant_id = #{q.tenantId}
  AND content.tenant_id = #{q.tenantId}
  AND runtime.tenant_id = #{q.tenantId}
  AND runtime.provision_status IN (0, 2)

  AND task.task_name LIKE CONCAT('%', #{q.taskNameLike}, '%') ESCAPE '!'


  AND runtime.run_status = #{q.runStatus}


  AND task.task_type = #{q.taskModeCode}


  AND JSON_CONTAINS(task.target_country_iso2s_snapshot, JSON_QUOTE(#{q.countryIso2}))


  AND (task.target_country_iso2s_snapshot IS NULL
    OR JSON_CONTAINS(task.target_country_iso2s_snapshot, 'null'))


  AND task.created_at >= #{q.createdAtStart}


  AND task.created_at < #{q.createdAtEnd}

mapper.update:
UPDATE hyperlink_task SET data_package_generation=#{generation},
  data_package_name_snapshot=#{packageName}, target_country_iso2s_snapshot=#{countryIso2s},
  updated_at=#{updatedAt}
WHERE id=#{id}

mapper.select:
SELECT 


ORDER BY task.created_at DESC, task.id DESC
LIMIT #{q.pageSize} OFFSET #{q.offset}
